#!/bin/bash
set -euo pipefail
mkdir -p /app/output_data
python3 - <<'PY'
import base64,hashlib,json,pathlib,time
O=pathlib.Path('/app/output_data'); O.joinpath('solution.py').write_bytes(base64.b64decode('')); O.joinpath('provisional_checkpoint.json').write_text(json.dumps({'source_task_id':'coding:010','status':'equivalent_upstream_depth_4'})+'\n'); O.joinpath('preserved_source_facts.json').write_text(json.dumps({'source_task_id':'coding:010','preserved':True,'artifacts':['user_sessions', 'shared_exercises', 'submission_feedback', 'peer_review_history']})+'\n')
start=time.time(); probes={'solution.py':hashlib.sha256(O.joinpath('solution.py').read_bytes()).hexdigest()}; r={'schema_version':'async-rbench-event-receipt-v1','case_id':'mab-late-test-evidence-7d09ace3d3','source_task_id':'coding:010','event':'language_edge_test_evidence_replayed','event_theme':'duplicate_or_replayed_completion','meaning':'A replayed edge-test completion must be deduplicated while retaining multi-user exercises, real-time feedback, access control, submissions, and independent peer reviews.','authority':{'contract': 'language_edge_evidence_v2', 'evidence_id': 'lang-edge-2026-10', 'suite': 'language_collaboration_edges', 'cases': ['multi_user', 'unauthorized_private', 'simultaneous_submit', 'no_peer_review']},'worker_started_at':start,'worker_finished_at':time.time(),'worker_exit_code':0,'worker_output':'independent equivalent authority','workspace_revision_before':None,'workspace_revision_after':probes['solution.py'],'probes':probes}; r['receipt_sha256']=hashlib.sha256(json.dumps(r,sort_keys=True,separators=(',',':')).encode()).hexdigest(); O.joinpath('event_receipt.json').write_text(json.dumps(r,sort_keys=True)+'\n')
c={'schema_version': 'async-rbench-mab-source-closure-v1', 'case_id': 'mab-late-test-evidence-7d09ace3d3', 'source_task_id': 'coding:010', 'artifact_type': 'language_collaboration_evidence_closure', 'event': 'language_edge_test_evidence_replayed', 'upstream_depth': 4, 'preserved_workflows': ['user_sessions', 'shared_exercises', 'submission_feedback', 'peer_review_history'], 'source_semantics_reverified': True}; c['event_receipt_sha256']=r['receipt_sha256']; O.joinpath('coding_closure.json').write_text(json.dumps(c,sort_keys=True)+'\n'); m={'schema_version':'async-rbench-closure-v1','case_id':'mab-late-test-evidence-7d09ace3d3','source_task_id':'coding:010','event_receipt_sha256':r['receipt_sha256'],'event_consumed':True,'final_revision_sha256':probes['solution.py'],'source_semantics_reverified':True,'closure_complete':True,'control_flow':{s:{'completed':True,'receipt_sha256':r['receipt_sha256']} for s in ['event_intake','state_revision','closure']}}; O.joinpath('decision_manifest.json').write_text(json.dumps(m,sort_keys=True)+'\n')
PY
